export function nextGeneration(liveCells: Cell[]): Cell[] {
  const isLive = ([x, y]: Cell): boolean =>
    liveCells.some(([liveX, liveY]) => liveX === x && liveY === y);

  const neighboursOf = ([x, y]: Cell): Cell[] =>
    NEIGHBOUR_OFFSETS.map(([dx, dy]) => [x + dx, y + dy]);

  const countLiveNeighbours = (cell: Cell): number =>
    neighboursOf(cell).filter(isLive).length;

  const survives = (cell: Cell): boolean =>
    countLiveNeighbours(cell) === NEIGHBOURS_NEEDED_TO_SURVIVE;

  const isBorn = (cell: Cell): boolean =>
    !isLive(cell) && countLiveNeighbours(cell) === NEIGHBOURS_NEEDED_TO_BE_BORN;

  const birthCandidates = liveCells.flatMap(neighboursOf);
  const born = birthCandidates.filter(
    (cell, index) =>
      isBorn(cell) &&
      birthCandidates.findIndex(([x, y]) => x === cell[0] && y === cell[1]) ===
        index,
  );

  return [...liveCells.filter(survives), ...born];
}

